-- R04.2: balance-deeper, the smallest root split there is.
-- R04.1: the cell distribution on the leaves that split creates, and the page
-- count it leaves.
--
-- Four 900-byte rows fill one 4096-byte page. The fifth forces the root to
-- split into an interior page with two leaves. Eight rows leave the tree two
-- levels deep: every row still reads back in key order -- listed one per line,
-- each with the key its payload carries, so the four rows below the split are
-- checked individually and not only through the aggregates -- the range id>4 is
-- answered through the interior node the split created, and the finished file
-- contains 4 pages. Stock sqlite3 3.50.2 replaying these same statements
-- answers 4 as well; the previous checkpoint answers 5, which is what this
-- case is here to tell apart.
CREATE TABLE t(id INTEGER PRIMARY KEY, v TEXT);
INSERT INTO t VALUES(1,''),(2,''),(3,''),(4,''),(5,''),(6,''),(7,''),(8,'');
SELECT count(*), sum(id), sum(length(v)) FROM t;
SELECT id, substr(v,1,3) FROM t ORDER BY id DESC LIMIT 2;
SELECT id, substr(v,1,3) FROM t ORDER BY id;
SELECT id FROM t WHERE id>4 ORDER BY id;
PRAGMA page_count;
